      models_note='نماذج المجموعتين 2–4 من إعداد حراء؛ ونموذج المجموعة 1 من نص الكتاب. اقبل كل إجابة صحيحة تُعلِّل.',
      levels_work=dict(rows=[['أُلَوِّنُ الرَّمْزَ الْمُناسِبَ.', 'أُلَوِّنُ 👍 أَوْ 👎.'], ['أَصِلُ الْمَوْقِفَ بِما يُناسِبُهُ.', 'أُلَوِّنُ الرَّمْزَ الْمُناسِبَ.'], ['أَخْتارُ الْكَلِمَةَ وَأَكْتُبُها.', 'أَنْسَخُ بِخَطٍّ جَميلٍ.']],
                         challenge='تَحَدّي الْأَبْطالِ: أُفَكِّرُ وَأَرْسُمُ مَوْقِفًا يُظْهِرُ ' + topic + '.'),
      value=d['value'], watani=d['watani'], quick=d['quick'], exit=d['exit'], mirror=d['mirror'], home=d['home'],
